//---------- transpose ----------

// Transpose N complex packets: a pure f64-lane permutation of the same
// memory words (each PacketXcd is just an interleaved view of PacketXd),
// so it delegates to the real-packet ptranspose from PacketMath.h. Needed
// by the GEBP rhs packing path (GeneralBlockPanelKernel.h) for
// complex GEMM.
template <int N>
EIGEN_DEVICE_FUNC inline void ptranspose(PacketBlock<PacketXcd, N>& kernel) {
  PacketBlock<PacketXd, N> real;
  for (int i = 0; i < N; i++) real.packet[i] = kernel.packet[i].v;
  ptranspose(real);
  for (int i = 0; i < N; i++) kernel.packet[i].v = real.packet[i];
}

